final class Session {
    private let connection: Connection
    init(connection: Connection) { self.connection = connection }
    deinit { connection.shutdown() }        // runs immediately before deallocation
    func roundTrip() throws {}
}
func handle() throws {
    let session = Session(connection: connect())   // released at scope exit
    defer { try? session.flush() }                 // optional explicit step
    try session.roundTrip()
}
